FROM rust:1.98.1-bookworm@sha256:93ce27a88655056a51dbdd8f5f2d7ddc071c7b0070fb288a37b5a285fc83971e AS chef
RUN cargo install cargo-chef --version 0.1.78 --locked
WORKDIR /app

FROM chef AS planner
COPY Cargo.toml Cargo.lock ./
COPY exposed ./exposed
RUN cargo chef prepare --recipe-path recipe.json

FROM chef AS builder
ARG CARGO_BUILD_JOBS=2
COPY --from=planner /app/recipe.json recipe.json
RUN cargo chef cook --release --locked --recipe-path recipe.json
COPY Cargo.toml Cargo.lock ./
COPY exposed ./exposed
COPY .sqlx ./.sqlx
ENV SQLX_OFFLINE=true
RUN cargo build --release --locked --package exposed --bin exposed
RUN ldd target/release/exposed

FROM debian:bookworm-slim@sha256:7c7b2c966bc9ee8cedfeef67e0e279108992c77681fa595db4a9d65c06ccc587 AS runtime
RUN apt-get update \
    && apt-get install --no-install-recommends -y ca-certificates libgcc-s1 \
    && rm -rf /var/lib/apt/lists/*
WORKDIR /app
COPY --from=builder /app/target/release/exposed /usr/local/bin/exposed
USER 10001:10001

FROM node:24-bookworm-slim@sha256:a5f4366e834695d5f363b920c104953a535d3a9864d1bdf74566a0ebe01daee5 AS frontend-builder
WORKDIR /app/frontend
COPY frontend/package.json frontend/package-lock.json ./
RUN npm ci
COPY frontend/ ./
RUN npm run build && npm prune --omit=dev

FROM node:24-bookworm-slim@sha256:a5f4366e834695d5f363b920c104953a535d3a9864d1bdf74566a0ebe01daee5 AS frontend-server
WORKDIR /app/frontend
COPY --from=frontend-builder /app/frontend/build ./build
COPY --from=frontend-builder /app/frontend/package.json ./package.json
COPY --from=frontend-builder /app/frontend/node_modules ./node_modules
ENV PORT=8080 HOST=0.0.0.0
USER 10001:10001
EXPOSE 8080
ENTRYPOINT ["node", "build"]
CMD []

FROM runtime AS migrate
COPY db/migrations/ /app/db/migrations/
ENTRYPOINT ["exposed", "migrate"]
CMD ["run", "--source", "/app/db/migrations"]

FROM runtime AS data
ENTRYPOINT ["exposed", "data"]
CMD ["--help"]

FROM runtime AS binary
HEALTHCHECK --interval=30s --timeout=3s --start-period=10s --retries=3 CMD ["exposed", "healthcheck"]
EXPOSE 6999
ENTRYPOINT ["exposed"]
CMD ["server"]
import { defineConfig, devices } from "@playwright/test";

export default defineConfig({
  testDir: "./tests",
  fullyParallel: true,
  forbidOnly: Boolean(process.env.CI),
  retries: 0,
  reporter: "list",
  use: {
    baseURL: "http://127.0.0.1:4173",
    ...devices["Desktop Chrome"],
    trace: "retain-on-failure",
  },
});
import { expect, test } from "./backend";

test("landing and methodology navigate without backend requests", async ({
  page,
  backend,
}) => {
  const requests: string[] = [];
  await backend.route("**/api/*", async (route) => {
    requests.push(route.request().url());
    await route.fulfill({ status: 500 });
  });
  await page.goto("/");
  await expect(page).toHaveTitle("Exposed");
  await expect(page.getByRole("heading", { level: 1 })).toHaveText(
    "Explore UK MPs' declared financial interests and the people and organisations behind them.",
  );
  await page.keyboard.press("Tab");
  await expect(
    page.getByRole("link", { name: "Skip to content" }),
  ).toBeFocused();
  await page.keyboard.press("Enter");
  await expect(page.locator("#landing")).toBeFocused();
  await page
    .locator("#landing")
    .getByRole("link", { name: "Methodology", exact: true })
    .click();
  await expect(page).toHaveURL(/\/methodology$/u);
  await expect(page).toHaveTitle("Methodology · Exposed");
  await expect(
    page.getByRole("link", {
      name: "official Register of Members' Financial Interests",
    }),
  ).toHaveAttribute("href", /parliament.uk/u);
  await page.goto("/methodology");
  await page.keyboard.press("Tab");
  await page.keyboard.press("Enter");
  await expect(page.locator("#methodology")).toBeFocused();
  await page.getByRole("link", { name: "Exposed home" }).click();
  await page.getByRole("link", { name: "Search MPs and funders" }).click();
  await expect(page).toHaveURL(/\/search$/u);
  await expect(page.getByRole("searchbox")).toHaveValue("");
  expect(requests).toEqual([]);
});

for (const viewport of [
  { width: 1440, height: 900 },
  { width: 1280, height: 720 },
  { width: 390, height: 844 },
  { width: 320, height: 568 },
]) {
  test(`landing fits ${viewport.width}px viewport`, async ({ page }) => {
    await page.setViewportSize(viewport);
    await page.goto("/");
    await page.evaluate(() => document.fonts.ready);
    expect(
      await page.evaluate(() => ({
        width: document.documentElement.scrollWidth,
        height: document.documentElement.scrollHeight,
      })),
    ).toEqual(viewport);
    for (const link of await page.locator("#landing a").all()) {
      const bounds = await link.boundingBox();
      expect(bounds?.height).toBeGreaterThanOrEqual(44);
    }
    await page.locator("#landing h1").evaluate((heading) => {
      heading.style.fontSize = "64px";
    });
    expect(
      await page.evaluate(() => document.documentElement.scrollWidth),
    ).toBe(viewport.width);
  });
}

for (const { query, canonical, status } of [
  { query: "?q=", canonical: "/search?q=", status: 307 },
  { query: "?strictness=0.42", canonical: "/search", status: 308 },
  {
    query: "?q=Example&strictness=0.42&extra=&q=second",
    canonical: "/search?q=Example&extra=&q=second",
    status: 308,
  },
  {
    query: "?q=&strictness=&extra=%20",
    canonical: "/search?q=&extra=+",
    status: 308,
  },
]) {
  test(`legacy root preserves ${query} without JavaScript`, async ({
    browser,
    baseURL,
    backend,
    request,
  }) => {
    await backend.route("**/api/search?*", (route) =>
      route.fulfill({ json: { entities: [] } }),
    );
    const response = await request.get(`/${query}`, { maxRedirects: 0 });
    expect(response.status()).toBe(status);
    expect(response.headers().location).toBe(canonical);
    const context = await browser.newContext({
      javaScriptEnabled: false,
      baseURL,
    });
    try {
      const page = await context.newPage();
      await page.goto(`/${query}`);
      expect(new URL(page.url()).pathname + new URL(page.url()).search).toBe(
        canonical,
      );
      await expect(page.getByRole("searchbox")).toHaveValue(
        new URLSearchParams(query).get("q") ?? "",
      );
    } finally {
      await context.close();
    }
  });
}

test("unrelated root parameters retain landing and unknown routes remain not found", async ({
  page,
}) => {
  await page.goto("/?utm_source=test");
  await expect(page.locator("#landing")).toBeVisible();
  await page.goto("/missing");
  await expect(
    page.getByRole("heading", { name: "Entity not found" }),
  ).toBeVisible();
});
